// Cross-language numerical conformance: invoke the sce-codegen CLI on every
// fixture declared in tests/forge/conformance/fixtures.json AND render the
// test harness itself from the shared Jinja2 template. Both outputs land
// under build/generated/conformance/kotlin/, which is wired into the jvmTest
// source set so the test binary compiles live codegen — no committed goldens
// on the conformance path. See SCE_FORGE.md Section 2.1.
//
// Task is configuration-cache-safe: inputs are declared properties and the
// work happens through ExecOperations.
abstract class GenerateForgeFixtures : DefaultTask() {
    @get:InputFile
    @get:PathSensitive(PathSensitivity.ABSOLUTE)
    abstract val sceCodegen: RegularFileProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val resourceDir: DirectoryProperty

    @get:InputFile
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val manifest: RegularFileProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val conformanceTemplateDir: DirectoryProperty

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val execOperations: ExecOperations

    @TaskAction
    fun generate() {
        val bin = sceCodegen.get().asFile
        if (!bin.canExecute()) {
            throw GradleException(
                "sce-codegen binary not found or not executable at ${bin.absolutePath}. " +
                "Build it first: " +
                "`cargo build --bin sce-codegen --features cli --release -p sce-build`",
            )
        }
        val res = resourceDir.get().asFile
        val out = outputDir.get().asFile
        val manifestFile = manifest.get().asFile
        out.deleteRecursively()
        out.mkdirs()

        // Pull the fixture name list from sce-codegen itself so this script
        // never has to parse JSON natively. The Rust binary owns the
        // manifest schema (see sce-build/src/conformance.rs).
        val listOut = ByteArrayOutputStream()
        execOperations.exec {
            commandLine(
                bin.absolutePath,
                "list-fixtures",
                "--manifest", manifestFile.absolutePath,
                "--format", "plain",
            )
            standardOutput = listOut
        }
        val fixtureNames = listOut.toString(Charsets.UTF_8)
            .lineSequence()
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .toList()

        // Step 1: per-fixture product code generation.
        for (fixture in fixtureNames) {
            execOperations.exec {
                commandLine(
                    bin.absolutePath,
                    "generate",
                    res.resolve("$fixture.scxml").absolutePath,
                    "--language", "kotlin",
                    "--output-dir", out.absolutePath,
                )
            }
        }

        // Step 2: render the NumericalConformanceTest.kt harness from the
        // shared template. No test code is hand-maintained in this module.
        execOperations.exec {
            commandLine(
                bin.absolutePath,
                "generate-conformance",
                "--language", "kotlin",
                "--manifest", manifestFile.absolutePath,
                "--output-dir", out.absolutePath,
            )
        }
    }
}

// Rebuild sce-codegen from the current sce-build sources when the Rust
// toolchain is available (local dev). Gradle's up-to-date check via
// inputs/outputs short-circuits the task when nothing changed; cargo's
// own incremental build handles any drift Gradle's input tracking misses.
// The value is eliminating the stale-binary foot-gun where a schema
// change in conformance.rs would otherwise be silently ignored by the
// Kotlin jvmTest calling the old binary.
//
// In CI, the conformance-kotlin job downloads a pre-built artifact from
// the build-codegen job and has no Rust toolchain; the `onlyIf` check
// evaluates PATH at task-execution time and skips this task, so
// GenerateForgeFixtures consumes the downloaded binary directly.
//
// The cargo-on-PATH check is inlined inside `onlyIf` on purpose: a top-
// level `fun` or `val` would be a script-level reference that Gradle's
// configuration cache refuses to serialize.
val buildSceCodegen by tasks.registering(Exec::class) {
    workingDir = rootProject.projectDir
    commandLine(
        "cargo", "build",
        "--bin", "sce-codegen",
        "--features", "cli",
        "--release",
        "-p", "sce-build",
    )
    inputs.dir(rootProject.layout.projectDirectory.dir("sce-build/src"))
        .withPathSensitivity(PathSensitivity.RELATIVE)
    inputs.file(rootProject.layout.projectDirectory.file("sce-build/Cargo.toml"))
        .withPathSensitivity(PathSensitivity.RELATIVE)
    outputs.file(rootProject.layout.projectDirectory.file("target/release/sce-codegen"))
    onlyIf {
        val path = System.getenv("PATH") ?: return@onlyIf false
        val sep = File.pathSeparator
        for (dir in path.split(sep)) {
            val candidate = File(dir, "cargo")
            if (candidate.exists() && candidate.canExecute()) {
                return@onlyIf true
            }
        }
        false
    }
}

val generateForgeFixtures by tasks.registering(GenerateForgeFixtures::class) {
    dependsOn(buildSceCodegen)
    sceCodegen.set(rootProject.layout.projectDirectory.file("target/release/sce-codegen"))
    resourceDir.set(rootProject.layout.projectDirectory.dir("tests/forge/resources"))
    manifest.set(rootProject.layout.projectDirectory.file("tests/forge/conformance/fixtures.json"))
    conformanceTemplateDir.set(
        rootProject.layout.projectDirectory.dir("tools/codegen/templates/forge/kotlin/conformance"),
    )
    outputDir.set(layout.buildDirectory.dir("generated/conformance/kotlin"))
}

kotlin {
    jvmToolchain(17)
    jvm()

    sourceSets {
        val commonMain by getting
        val commonTest by getting {
            dependencies {
                implementation(kotlin("test"))
            }
        }
        val jvmTest by getting {
